def unique_jobs(rows):
    seen = set()
    result = []
    for row in rows:
        source = row.get('source', '')
        source_id = row.get('source_id')
        if source is None or source == '':
            key = ('__MISSING__', source_id)
        else:
            key = (source, source_id)

        if key not in seen:
            seen.add(key)
            result.append(row)
    return result
